public int[] maxCircle(int[][] queries) {
    Map<Integer, Set<Integer>> circleOf = new HashMap<>();
    int[] result = new int[queries.length];
    int best = 0;
    for (int qi = 0; qi < queries.length; qi++) {
        int a = queries[qi][0], b = queries[qi][1];
        Set<Integer> sa = circleOf.computeIfAbsent(a, x -> new HashSet<>(Set.of(x)));
        Set<Integer> sb = circleOf.computeIfAbsent(b, x -> new HashSet<>(Set.of(x)));
        if (sa != sb) {
            if (sa.size() < sb.size()) { Set<Integer> t = sa; sa = sb; sb = t; }
            for (int member : sb) {       // pour smaller set into larger
                sa.add(member);
                circleOf.put(member, sa);
            }
            best = Math.max(best, sa.size());
        }
        result[qi] = best;
    }
    return result;
}

