def max_circle(self, queries: list[list[int]]) -> list[int]:
    circle_of: dict[int, set[int]] = {}
    result: list[int] = []
    best = 0
    for a, b in queries:
        if a not in circle_of:
            circle_of[a] = {a}
        if b not in circle_of:
            circle_of[b] = {b}
        sa, sb = circle_of[a], circle_of[b]
        if sa is not sb:
            if len(sa) < len(sb):
                sa, sb = sb, sa
            for member in sb:             # pour smaller set into larger
                sa.add(member)
                circle_of[member] = sa
            best = max(best, len(sa))
        result.append(best)
    return result

