private Map<Integer, Integer> parent = new HashMap<>();
private Map<Integer, Integer> size = new HashMap<>();

private int find(int x) {
    parent.putIfAbsent(x, x);
    size.putIfAbsent(x, 1);
    int root = x;
    while (parent.get(root) != root) root = parent.get(root);
    while (parent.get(x) != root) {        // path compression
        int next = parent.get(x);
        parent.put(x, root);
        x = next;
    }
    return root;
}

public int[] maxCircle(int[][] queries) {
    int[] result = new int[queries.length];
    int best = 0;
    for (int qi = 0; qi < queries.length; qi++) {
        int ra = find(queries[qi][0]);
        int rb = find(queries[qi][1]);
        if (ra != rb) {
            if (size.get(ra) < size.get(rb)) { int t = ra; ra = rb; rb = t; }
            parent.put(rb, ra);             // union by size
            int merged = size.get(ra) + size.get(rb);
            size.put(ra, merged);
            best = Math.max(best, merged);
        }
        result[qi] = best;
    }
    return result;
}

