def max_circle(self, queries: list[list[int]]) -> list[int]:
    parent: dict[int, int] = {}
    size: dict[int, int] = {}

    def find(x: int) -> int:
        if x not in parent:
            parent[x] = x
            size[x] = 1
            return x
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:            # path compression
            parent[x], x = root, parent[x]
        return root

    result: list[int] = []
    best = 0
    for a, b in queries:
        ra, rb = find(a), find(b)
        if ra != rb:
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra                 # union by size
            size[ra] += size[rb]
            best = max(best, size[ra])
        result.append(best)
    return result
